		assertEquals(40, tob.getKillCount());
		// Entry Mode completions add nothing
		assertEquals(10 * 0.027 * 8 / 19, row(tob, "Avernic defender hilt").getExpected(), 1e-12);
		assertEquals(10 / 650.0, row(tob, "Lil' zik").getExpected(), 1e-12);
	}

